  private async recipeRequirements(db: any, tenantId: string, items: Array<{ recipeId: string; quantitySold: number }>) { const result = new Map<string, { quantity: number; cost: number }>(); for (const item of items) { const recipe = await db.restaurantRecipe.findFirst({ where: { id: item.recipeId, tenantId, status: RestaurantRecipeStatus.ACTIVE } }); if (!recipe) this.bad('Receta activa no encontrada'); const lines = await db.restaurantRecipeIngredient.findMany({ where: { recipeId: recipe.id } }); for (const line of lines) { const wasteFactor = 1 + Number(line.wastePercentage ?? 0) / 100; const quantity = Number(line.convertedInventoryQuantity) * Number(item.quantitySold) * wasteFactor; const current = result.get(line.ingredientId) ?? { quantity: 0, cost: 0 }; result.set(line.ingredientId, { quantity: current.quantity + quantity, cost: current.cost + quantity * Number(line.calculatedCost ?? 0) }); } } return result; }
